from solution import word_frequency

def test_basic():
    result = word_frequency('the cat sat on the mat')
    assert result['the'] == 2
    assert result['cat'] == 1

def test_case_insensitive():
    result = word_frequency('Hello hello HELLO')
    assert result['hello'] == 3

def test_punctuation():
    result = word_frequency('one, two. one!')
    assert result['one'] == 2
    assert result['two'] == 1

def test_empty():
    assert word_frequency('') == {}

def test_single_word():
    assert word_frequency('python') == {'python': 1}
